// C++ inline keyword: A hint to the compiler
inline int fast_add(int a, int b) {
    return a + b;
}

class Utility {
public:
    // Implied inline due to definition in class body
    int get_id() const { return 100; }
};

// GCC/Clang specific strong hint (optimization related)
// Not guaranteed, but much more aggressive
__attribute__((always_inline))
static int zero_check(int x) {
    return x == 0;
}

// Compiler checks:
// 1. Function size (too large -> less likely to inline).
// 2. Optimization level (-O2/-O3 enables aggressive inlining).
// Benefit: Enables optimizations like Constant Folding.
